mapper.select:
select * from (SELECT ETR_ENTRUST.ENTRUST_STATUS entrustStatus, trunc(nvl(NVL(T5.FINISH_AMT, 0)+ NVL(T7.ENT_FINISH_AMT*100, 0),0)/(ETR_ENTRUST.ENTRUST_NUM*100),4)*100 transactioncom, ETR_ENTRUST.INV_MANAGER_ID invManagerId, (SELECT real_name FROM SYS_USER WHERE user_name = ETR_ENTRUST.INV_MANAGER_ID) invManagerName, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName, (select sec_acct_name from stl_sec_acct_info where stl_sec_acct_info.sec_acct_id = ETR_ENTRUST_ADD.SEC_ACCT_ID) as secAcctName, ETR_ENTRUST.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, ETR_ENTRUST_ADD.SETTLE_SPREED settleSpreed, ETR_ENTRUST.PS ps, ETR_ENTRUST.ENTRUST_NUM/100 entrustNum, (NVL(T5.FINISH_AMT,0)+NVL(T7.ENT_FINISH_AMT*100,0))/10000 finishAmt, NVL(ETR_ENTRUST.ENTRUST_NUM, 0)/100 - NVL(T5.FINISH_AMT,0)/10000 - NVL(T7.ENT_FINISH_AMT,0)/100 avaNum, (NVL(ETR_ENTRUST.ENTRUST_NUM,0) /100 -NVL(T5.FINISH_AMT, 0)/10000 ) - NVL(T7.ENT_FINISH_AMT,0)/100 AS entrustAvaNum, ETR_ENTRUST.PRICE price, ETR_ENTRUST_ADD.MATURE_YIELD * 100 matureYield, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST_ADD.QUOTE_TYPE quoteType, ETR_ENTRUST.BUSINESS_MODEL businessModel,
MST_CFETS_CUSTOMER_INFO.PARTY_ID mySide,
MST_CFETS_CUSTOMER_INFO.PARTY_ABBR mySideAbbr,
(SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = #{loginUserId} AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID) ) mySideTrader,
(SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_NAME FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = #{loginUserId} AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID) ) mySideTraderName,
MST_CFETS_CI.PARTY_ID counterId,
MST_CFETS_CI.PARTY_ABBR counterName,
ETR_ENTRUST.COUNTER_TRADER counterTrader,
MST_CFETS_CT.TRADER_NAME counterTraderName, ETR_ENTRUST_ADD.EXER_YIELD * 100 exerYield, NVL(ETR_ENTRUST_ADD.CAL_MODE,DECODE(ETR_ENTRUST_ADD.CALCULATE_FIELD,'price','01','matureYield','02','exerYield','03','01')) calculateField, FIN_PRODUCT.IS_RIGHT isRight, FIN_PRODUCT_TYPE.TYPE_4 assetTypeOne, FIN_PRODUCT_TYPE.TYPE_11 type11, ETR_ENTRUST.REMARK remark, ETR_ENTRUST.CCY settleCcy, ETR_ENTRUST.CCY ccy, IBU_PORTFOLIO_ACCT_RELA.CFETS_ACCT_TYPE secAcctSource, IBU_PORTFOLIO_ACCT_RELA.PARTY_ID partyId, trunc(NVL(T8.totalShareAmt,0)/(ETR_ENTRUST.ENTRUST_NUM),4)*100 tradeFinishPercent, ETR_ENTRUST.PRICE_MODEL priceModel, ETR_ENTRUST_ADD.SEC_ACCT_ID secManageAcctId, PA_PTL_PORTFOLIO.PORTFOLIO_SERIES portfolioSeries, ETR_ENTRUST_ADD.OUR_ENT_NUM*100 OUR_ENT_NUM, ETR_ENTRUST_ADD.LENDIN_ENT_NUM*100 LENDIN_ENT_NUM, ETR_ENTRUST_ADD.SELL_ABLE_NUM*100 SELL_ABLE_NUM, ETR_ENTRUST.TRADE_MARKET, ETR_ENTRUST.ENTRUST_DATE entrustDate, ETR_ENTRUST_ADD.FULL_PRICE unitFprice, to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME,'hh24:mi:ss') transmitTime, ROUND(NVL(T8.totalShareAmt,0)/100) finishDealAmt, ROUND((NVL(ETR_ENTRUST.ENTRUST_NUM, 0) - NVL(T8.totalShareAmt,0))/100) avaDealAmt, D.ITEM_VALUE entrustStatusStr, E.ITEM_VALUE psStr, F.ITEM_VALUE priceModelStr, H.ITEM_VALUE settleSpreedStr, G.ITEM_VALUE businessModelStr, I.ITEM_VALUE tradeMarketStr FROM ETR_ENTRUST INNER JOIN PTL_PORTFOLIO ON ETR_ENTRUST.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = PA_PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN ETR_DISTRIBUTE ON ETR_ENTRUST.ENTRUST_ID = ETR_DISTRIBUTE.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS
INNER JOIN (SELECT DISTINCT T3.TRADE_ID FROM TRDQUTO_MATCH_INFO T1 INNER JOIN REG_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.PRE_TRADE_ID = T2.TOTLE_TRADE_ID INNER JOIN TRD_PRODUCT_DEAL T3 ON T3.TOTLE_TRADE_ID = T1.TRD_ID WHERE TRD_CONF_STATUS = '1') REG ON REG.TRADE_ID = ETR_FINISH_STATUS.TRADE_ID GROUP BY ENTRUST_ID) T6 ON ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN( SELECT ENTRUST_ID, SUM(ENT_FINISH_AMT) AS ENT_FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T7 ON ETR_ENTRUST.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN (select sum(SHARE_AMT) totalShareAmt,tpda.ENTRUST_ID from TRD_PRODUCT_DEAL tpd left join TRD_PRODUCT_DEAL_ADD tpda on tpd.TRADE_ID = tpda.TRADE_ID where tpd.IS_CANCEL = 'N' and tpd.TRADE_STATUS = '01' group by tpda.ENTRUST_ID ) T8 ON T8.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN FIN_PRODUCT ON ETR_ENTRUST.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA ON ETR_ENTRUST.PORTFOLIO_ID = IBU_PORTFOLIO_ACCT_RELA.PORTFOLIO_ID AND IBU_PORTFOLIO_ACCT_RELA.CFETS_ACCT_TYPE = '01' LEFT JOIN MST_CFETS_CUSTOMER_INFO ON IBU_PORTFOLIO_ACCT_RELA.PARTY_ID = MST_CFETS_CUSTOMER_INFO.PARTY_ID LEFT JOIN SYS_USER ON ETR_ENTRUST.CREATE_USER = SYS_USER.USER_NAME LEFT JOIN SYS_USER_ADD ON SYS_USER.USER_ID = SYS_USER_ADD.USER_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER ON SYS_USER_ADD.IBU_TRADER = MST_CFETS_CUSTOMER_TRADER.TRADER_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MST_CFETS_CT ON MST_CFETS_CT.TRADER_ID = ETR_ENTRUST.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = ETR_ENTRUST.COUNTER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO MST_CFETS_CI ON MST_CFETS_CI.PARTY_NAME = MCP.COUNTER_NAME LEFT JOIN (SELECT C.ENTRUST_ID, SUM(nvl(C.SHARE_AMT, 0)) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID LEFT JOIN IBU_QUOTE_ETR_RE C ON A.QUOTE_ID = C.QUOTE_ID WHERE B.TRADE_STATUS = '07' GROUP BY C.ENTRUST_ID) C ON C.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT A.ENTRUST_ID, nvl(A.SHARE_AMT, 0) * 100 totalShareAmt FROM IBU_QUOTE_BOND A LEFT JOIN IBU_QUOTE_BOND_DET B ON A.QUOTE_ID = B.QUOTE_ID WHERE B.TRADE_STATUS = '07') C2 ON C2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ENTRUST_STATUS')D ON ETR_ENTRUST.ENTRUST_STATUS = D.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'PS')E ON ETR_ENTRUST.PS = E.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'PRICE_MODEL')F ON ETR_ENTRUST.PRICE_MODEL = F.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'BUSINESS_MODEL')G ON ETR_ENTRUST.BUSINESS_MODEL = G.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ACCOUNT_SPEED')H ON DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED,0,'01',1,'02',2,'03') = H.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'TRADE_PLACE')I ON ETR_ENTRUST.TRADE_MARKET = I.ITEM_CODE WHERE ETR_ENTRUST.FINPROD_TYPE2 = #{finprodType2} AND ETR_ENTRUST.TRADE_MARKET in (#{tradeMarket01},#{tradeMarket02}) AND ETR_ENTRUST.TRADE_MARKET_MODE = #{tradeMarketMode} AND ETR_ENTRUST.PS IN (#{psT01}, #{psT02},#{psT03}) AND ETR_ENTRUST.ENTRUST_STATUS IN (#{entrustStatusUnAccept}, #{entrustStatusAccept}, #{entrustStatusComple},#{entrustStatusReturn})
AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
AND ETR_ENTRUST.ENTRUST_DATE >= to_date(#{entrustDateStart}, 'yyyy-MM-dd')
AND ETR_ENTRUST.ENTRUST_DATE <= to_date(#{entrustDateEnd}, 'yyyy-MM-dd')
AND ETR_ENTRUST.PORTFOLIO_ID IN
#{item}
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodMarketId}
AND FIN_PRODUCT.FINPROD_ID = #{finprodId}
AND ETR_ENTRUST.PS = #{ps}
AND ETR_ENTRUST.PRICE_MODEL = #{priceModel}
AND ETR_ENTRUST.ENTRUST_ID = #{entrustId}
AND DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpeed}
AND DECODE(ETR_ENTRUST_ADD.SETTLE_SPREED, 0, '01', 1, '02') = #{settleSpreedCode}
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST.INV_MANAGER_ID IN
#{item}
AND FIN_PRODUCT.FINPROD_MARKET_ID IN
#{item}
AND ETR_ENTRUST.TRADE_MARKET IN
#{item}
AND ETR_ENTRUST.PS IN
#{item}
AND ETR_ENTRUST.PRICE_MODEL IN
#{item}
AND ETR_ENTRUST_ADD.SETTLE_SPREED IN
DECODE(#{item}, '01', 0, '02', 1)
and ETR_ENTRUST_ADD.SEC_ACCT_ID = #{secManageAcctId}
AND IBU_PORTFOLIO_ACCT_RELA.PARTY_ID = #{mySide}
AND ETR_DISTRIBUTE.TRADER = #{loginUserId}
AND STL_SEC_ACCT_INFO.SEC_ACCT_SOURCE = #{secAcctSource}
and ETR_ENTRUST.ENTRUST_ID in
#{item}
and ETR_ENTRUST.ENTRUST_ID in
#{item}
and ETR_ENTRUST.ENTRUST_ID not in
#{item}
order by decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7),ETR_ENTRUST_ADD.TRANSMIT_TIME,ETR_ENTRUST.FINPROD_ID,ETR_ENTRUST.ps)
( entrustStatusStr like '%' || #{search} || '%' OR psStr like '%' || #{search} || '%' OR priceModelStr like '%' || #{search} || '%' OR businessModelStr like '%' || #{search} || '%' OR settleSpreedStr like '%' || #{search} || '%' OR tradeMarketStr like '%' || #{search} || '%' OR portfolioId LIKE '%' || #{search} || '%' OR portfolioName LIKE '%' || #{search} || '%' OR finprodMarketId LIKE '%' || #{search} || '%' OR finprodAbbr LIKE '%' || #{search} || '%' OR secManageAcctId LIKE '%' || #{search} || '%' OR secAcctName LIKE '%' || #{search} || '%' OR invManagerName LIKE '%' || #{search} || '%' OR remark LIKE '%' || #{search} || '%' OR to_char(VDATE,'yyyy-MM-dd') LIKE '%' || #{search} || '%' OR to_char(MDATE,'yyyy-MM-dd') LIKE '%' || #{search} || '%' OR entrustId LIKE '%' || #{search} || '%' OR transmitTime LIKE '%' || #{search} || '%' OR to_char(transactioncom,'FM99990.9990')=#{search} or transactioncom||'' =#{search} or to_char(tradeFinishPercent,'FM99990.9990')=#{search} or tradeFinishPercent||'' =#{search} or to_char(entrustNum,'FM99990.9990')=#{search} or entrustNum||'' =#{search} or to_char(price,'FM99990.9990')=#{search} or price||'' =#{search} or to_char(matureYield,'FM99990.9990')=#{search} or matureYield||'' =#{search} or to_char(exerYield,'FM99990.9990')=#{search} or exerYield||'' =#{search} or to_char(entrustDate,'yyyy-MM-dd')||'' =#{search} or to_char(entrustDate,'yyyy-MM-dd')=#{year}||'-'||#{search} or replace(to_char(entrustDate,'yyyy-MM-dd'),'-','/')=#{search} or replace(to_char(entrustDate,'yyyy-MM-dd'),'-','/')=#{year}||'/'||#{search} )
order by ${pageMode.sort} ${pageMode.direction}

select count(1)
from FIN_EXERCISE_PLAN
where
    FINPROD_ID = #{finprodId}
    and EXERCISE_DATE > = #{sysDate,jdbcType=DATE}

        SELECT V.SEC_ACCT_ID
          FROM PTL_SEC_ACCT PSA, STL_SEC_ACCT_INFO V
          LEFT JOIN FIN_PRODUCT R
		ON R.REGIST_ORG = V.REGIST_ORG
	 WHERE PSA.ACCT_NO = V.SEC_ACCT_ID
	   AND V.SEC_ACCT_TYPE = 'SEC'
	   AND V.TRADE_PLACE = #{tradeMarket}
	   AND PSA.PORTFOLIO_ID = #{portfolioId}
	   AND R.FINPROD_ID = #{finprodId}

select count(1)
from FIN_EXERCISE_PLAN
where
    FINPROD_ID = #{finprodId}
    and EXERCISE_DATE > = #{sysDate,jdbcType=DATE}

SELECT T1.TRADE_STATUS validStatus, '04' QUOTE_TYPE, T3.TRADE_DATE settleDate, T1.PS, T1.FINPROD_ID, T4.FINPROD_MARKET_ID , T4.FINPROD_ABBR , '' TRADE_STATUS, '' SEND_STATUS, T1.SHARE_AMT/100 SHARE_AMT, T1.UNIT_CPRICE price, T1.YIELD matureYield, T1.EXER_YIELD exerYield, T1.SETTLE_SPEED , '' quoteRoleType, T1.OU_PARTY_ID , T1.OU_TRADER_ID , T1.COUNTER_ID , T1.COUNTER_TRADER, T6.PARTY_ABBR ouPartyName , T10.REAL_NAME ouTraderName,
T8.COUNTER_NAME cpPartyName, case when T7.TRADER_NAME is not null then T7.TRADER_NAME else T1.COUNTER_TRADER end cpTraderName, NULL reqEffTime, NULL resEffTime, NULL shareAmtHun, T1.TOTLE_TRADE_ID quoteId, T2.TRD_ID TRD_ID, T1.REMARK FROM REG_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRDQUTO_MATCH_INFO T2 ON T2.PRE_TRADE_ID = T1.TOTLE_TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T3.TOTLE_TRADE_ID = T2.TRD_ID LEFT JOIN FIN_PRODUCT T4 ON T4.FINPROD_ID = T1.FINPROD_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER T5 ON T5.TRADER_ID = T1.OU_TRADER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO T6 ON T6.PARTY_ID = T1.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER T7 ON T7.TRADER_ID = T1.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY T9 ON T9.COUNTER_ID = T1.COUNTER_ID LEFT JOIN MST_COUNTER_PARTY T8 ON T8.COUNTER_ID = T1.COUNTER_ID LEFT JOIN SYS_USER T10 ON T10.USER_NAME = T1.OU_TRADER_ID WHERE EXISTS ( SELECT 1 FROM REG_FIN_PRODUCT_DEAL T9 WHERE T9.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND (T1.IS_CANCEL = 'N' OR T1.IS_CANCEL IS NULL)
AND T9.ENTRUST_ID= #{entrustId}
)
UNION ALL SELECT '04' validStatus, '04' QUOTE_TYPE, null settleDate, T1.PS, T1.FINPROD_ID, T4.FINPROD_MARKET_ID , T4.FINPROD_ABBR , '' TRADE_STATUS, '' SEND_STATUS, T1.SHARE_AMT/100 SHARE_AMT, T1.UNIT_CPRICE price, T1.YIELD matureYield, T1.EXER_YIELD exerYield, T1.SETTLE_SPEED , '' quoteRoleType, T1.OU_PARTY_ID , T1.OU_TRADER_ID , T1.COUNTER_ID , T1.COUNTER_TRADER, T6.PARTY_ABBR ouPartyName , T10.REAL_NAME ouTraderName, T8.COUNTER_NAME cpPartyName, CASE WHEN T7.TRADER_NAME IS NOT NULL THEN T7.TRADER_NAME ELSE T1.COUNTER_TRADER END cpTraderName, NULL reqEffTime, NULL resEffTime, NULL shareAmtHun, T1.TOTLE_TRADE_ID quoteId, '' TRD_ID, T1.REMARK FROM WFL_REG_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT T4 ON T4.FINPROD_ID = T1.FINPROD_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER T5 ON T5.TRADER_ID = T1.OU_TRADER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO T6 ON T6.PARTY_ID = T1.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER T7 ON T7.TRADER_ID = T1.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY T9 ON T9.COUNTER_ID = T1.COUNTER_ID LEFT JOIN MST_COUNTER_PARTY T8 ON T8.COUNTER_ID = T1.COUNTER_ID LEFT JOIN SYS_USER T10 ON T10.USER_NAME = T1.OU_TRADER_ID WHERE EXISTS ( SELECT 1 FROM WFL_REG_FIN_PRODUCT_DEAL T9 WHERE T9.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID
AND T9.ENTRUST_ID= #{entrustId}
)
UNION ALL select y.VALID_STATUS validStatus ,y.I_Q_B_QUOTE_TYPE ,y.I_Q_B_SETTLE_DATE settleDate ,y.I_Q_B_PS ps ,y.I_Q_B_FINPROD_ID FINPROD_ID ,y.I_Q_B_FINPROD_MARKET_ID FINPROD_MARKET_ID ,y.EXT_FINPROD_ABBR FINPROD_ABBR ,y.I_Q_B_TRADE_STATUS TRADE_STATUS ,y.I_Q_B_SEND_STATUS SEND_STATUS ,CASE WHEN y.I_Q_B_D_SHARE_AMT IS NULL THEN y.I_Q_B_SHARE_AMT / 100 ELSE y.I_Q_B_D_SHARE_AMT/100 END SHARE_AMT ,y.I_Q_B_D_UNIT_FPRICE price ,y.I_Q_B_D_YIELD matureYield ,y.I_Q_B_D_EXER_YIELD exerYield ,y.I_Q_B_SETTLE_SPEED SETTLE_SPEED ,y.I_Q_B_QUOTE_ROLE_TYPE quoteRoleType ,y.I_Q_B_OU_PARTY_ID OU_PARTY_ID ,y.I_Q_B_OU_TRADER_ID OU_TRADER_ID ,y.I_Q_B_D_CP_PARTY_ID COUNTER_ID ,y.I_Q_B_D_CP_TRADER COUNTER_TRADER ,y.EXT_PARTY_ABBR ouPartyName ,y.EXT_OUTRADER_NAME ouTraderName ,y.I_Q_B_D_CP_PARTY_NAME cpPartyName ,y.I_Q_B_D_CP_TRADER_NAME cpTraderName ,y.I_Q_B_EFF_TIME reqEffTime ,y.I_Q_B_D_RE_EFF_TIME resEffTime ,CASE WHEN y.I_Q_B_QUOTE_TYPE = '02' THEN I_Q_B_D_PRIN_AMT/10000 ELSE NULL END shareAmtHun ,y.I_Q_B_QUOTE_ID quoteId ,y.I_Q_B_D_EXECID TRD_ID ,y.I_Q_B_REMARK REMARK from (select a.QUOTE_ID AS I_Q_B_QUOTE_ID, a.QUOTE_TYPE AS I_Q_B_QUOTE_TYPE, a.QUOTE_ROLE_TYPE AS I_Q_B_QUOTE_ROLE_TYPE, a.VERSION AS I_Q_B_VERSION, a.EXE_TYPE AS I_Q_B_EXE_TYPE, a.P_QUOTE_ID AS I_Q_B_P_QUOTE_ID, a.CFETS_QUOTE_ID AS I_Q_B_CFETS_QUOTE_ID, a.FINPROD_ID AS I_Q_B_FINPROD_ID, a.FINPROD_TYPE2 AS I_Q_B_FINPROD_TYPE2, a.BRANCH AS I_Q_B_BRANCH, CASE WHEN z.QUOTE_ID IS NOT null THEN z.PORTFOLIO_ID ELSE a.PORTFOLIO_ID END I_Q_B_PORTFOLIO_ID, CASE WHEN z.QUOTE_ID IS NOT null THEN z.ENTRUST_ID ELSE a.ENTRUST_ID END I_Q_B_ENTRUST_ID, a.QUOTE_DATE AS I_Q_B_QUOTE_DATE, /*a.SETTLE_DATE AS I_Q_B_SETTLE_DATE,*/ TT2.TRADE_DATE AS I_Q_B_SETTLE_DATE, a.SETTLE_SPEED AS I_Q_B_SETTLE_SPEED, a.DELIVERY_TYPE AS I_Q_B_DELIVERY_TYPE, a.SETT_TYPE AS I_Q_B_SETT_TYPE, a.SETT_CCY AS I_Q_B_SETT_CCY, a.PS AS I_Q_B_PS, a.SHARE_AMT AS I_Q_B_SHARE_AMT, a.FPRICE_AMT AS I_Q_B_FPRICE_AMT, a.TRADE_STATUS AS I_Q_B_TRADE_STATUS, a.SEND_STATUS A