7, m.TRADER_NAME AS EXT_OUTRADER_NAME, n.PARTY_ABBR AS EXT_PARTY_ABBR, n.PARTY_NAME AS EXT_PARTY_NAME, n.PARTY_CUSTOMER_ID AS EXT_PARTY_CUSTOMER_ID, n.PARTY_ABBR_EN AS EXT_PARTY_ABBR_EN, n.PARTY_NAME_EN AS EXT_PARTY_NAME_EN, a.WORKFLOW_STATUS as VALID_STATUS, case when z.PORTFOLIO_ID IS NOT null then 'Y' else 'N' end ISDZH, round((c.mdate-a.QUOTE_DATE)/365,2) pendingPeriod from (select nvl(a.QUOTE_ID, b.QUOTE_ID) QUOTE_ID, nvl(a.QUOTE_TYPE, b.QUOTE_TYPE) QUOTE_TYPE, nvl(a.QUOTE_ROLE_TYPE, b.QUOTE_ROLE_TYPE) QUOTE_ROLE_TYPE, nvl(a.VERSION, b.VERSION) VERSION, nvl(a.EXE_TYPE, b.EXE_TYPE) EXE_TYPE, nvl(a.P_QUOTE_ID, b.P_QUOTE_ID) P_QUOTE_ID, nvl(a.CFETS_QUOTE_ID, b.CFETS_QUOTE_ID) CFETS_QUOTE_ID, nvl(a.FINPROD_ID, b.FINPROD_ID) FINPROD_ID, nvl(a.FINPROD_TYPE2, b.FINPROD_TYPE2) FINPROD_TYPE2, nvl(a.BRANCH, b.BRANCH) BRANCH, nvl(a.PORTFOLIO_ID, b.PORTFOLIO_ID) PORTFOLIO_ID, nvl(a.ENTRUST_ID, b.ENTRUST_ID) ENTRUST_ID, nvl(a.QUOTE_DATE, b.QUOTE_DATE) QUOTE_DATE, nvl(a.SETTLE_DATE, b.SETTLE_DATE) SETTLE_DATE, nvl(a.SETTLE_SPEED, b.SETTLE_SPEED) SETTLE_SPEED, nvl(a.DELIVERY_TYPE, b.DELIVERY_TYPE) DELIVERY_TYPE, nvl(a.SETT_TYPE, b.SETT_TYPE) SETT_TYPE, nvl(a.SETT_CCY, b.SETT_CCY) SETT_CCY, nvl(a.PS, b.PS) PS, nvl(a.SHARE_AMT, b.SHARE_AMT) SHARE_AMT, nvl(a.FPRICE_AMT, b.FPRICE_AMT) FPRICE_AMT, nvl(a.TRADE_STATUS, b.TRADE_STATUS) TRADE_STATUS, nvl(a.SEND_STATUS, b.SEND_STATUS) SEND_STATUS, nvl(a.EFF_TIME, b.EFF_TIME) EFF_TIME, nvl(a.OU_PARTY_ID, b.OU_PARTY_ID) OU_PARTY_ID, nvl(a.OU_TRADER_ID, b.OU_TRADER_ID) OU_TRADER_ID, nvl(a.B_VERSION, b.B_VERSION) B_VERSION, nvl(a.MY_ACCT_NO, b.MY_ACCT_NO) MY_ACCT_NO, nvl(a.SEC_MANAGE_ACCT_ID, b.SEC_MANAGE_ACCT_ID) SEC_MANAGE_ACCT_ID, nvl(a.BRANCH_ID, b.BRANCH_ID) BRANCH_ID, nvl(a.REMARK, b.REMARK) REMARK, nvl(a.CREATE_USER, b.CREATE_USER) CREATE_USER, nvl(a.CREATE_TIME, b.CREATE_TIME) CREATE_TIME, nvl(a.CREATE_DEPT, b.CREATE_DEPT) CREATE_DEPT, nvl(a.UPDATE_USER, b.UPDATE_USER) UPDATE_USER, nvl(a.UPDATE_TIME, b.UPDATE_TIME) UPDATE_TIME, nvl(a.WORKFLOW_STATUS, '01') AS WORKFLOW_STATUS FROM WFL_IBU_QUOTE_BOND2 a FULL JOIN IBU_QUOTE_BOND B ON A.QUOTE_ID = B.QUOTE_ID) a left join ( SELECT iqbd.det_id, iqbd.req_id, iqbd.version, iqbd.cfets_req_id, xx.quote_id, CASE WHEN iqbd.cp_party_id IS NULL THEN xx.cp_party_id ELSE iqbd.cp_party_id END cp_party_id, CASE WHEN iqbd.cp_trader IS NULL THEN xx.cp_trader ELSE iqbd.cp_trader END cp_trader, CASE WHEN mm.TRADER_NAME IS NULL THEN xx.TRADER_NAME ELSE mm.TRADER_NAME END TRADER_NAME, CASE WHEN nn.PARTY_ABBR IS NULL THEN xx.PARTY_ABBR ELSE nn.PARTY_ABBR END PARTY_ABBR, iqbd.unit_cprice, iqbd.unit_int, iqbd.unit_fprice, iqbd.par_value, iqbd.share_amt, iqbd.prin_amt, iqbd.par_value_amt, iqbd.cprice_amt, iqbd.int_amt, iqbd.fprice_amt, iqbd.yield, iqbd.exer_yield, iqbd.calculate_field, iqbd.trade_status, iqbd.send_status, iqbd.execid, iqbd.re_eff_time, NULL workflow_id, NULL workflow_status, iqbd.remark, iqbd.create_user, iqbd.create_time, iqbd.create_dept, iqbd.update_user, iqbd.update_time FROM ( SELECT x.quote_id, LISTAGG(x.cp_party_id, ',') WITHIN GROUP( ORDER BY x.quote_id) AS cp_party_id, LISTAGG(x.cp_trader, ',') WITHIN GROUP( ORDER BY x.quote_id) AS cp_trader, LISTAGG(m.TRADER_NAME, ',') WITHIN GROUP( ORDER BY x.quote_id) AS TRADER_NAME, LISTAGG(n.PARTY_ABBR, ',') WITHIN GROUP( ORDER BY x.quote_id) AS PARTY_ABBR FROM ( SELECT NVL(a.det_id, b.det_id) det_id, NVL(a.req_id, b.req_id) req_id, NVL(a.version, b.version) version, NVL(a.cfets_req_id, b.cfets_req_id) cfets_req_id, NVL(a.quote_id, b.quote_id) quote_id, NVL(a.cp_party_id, b.cp_party_id) cp_party_id, NVL(a.cp_trader, b.cp_trader) cp_trader, NVL(a.unit_cprice, b.unit_cprice) unit_cprice, NVL(a.unit_int, b.unit_int) unit_int, NVL(a.unit_fprice, b.unit_fprice) unit_fprice, NVL(a.par_value, b.par_value) par_value, NVL(a.share_amt, b.share_amt) share_amt, NVL(a.prin_amt, b.prin_amt) prin_amt, NVL(a.par_value_amt, b.par_value_amt) par_value_amt, NVL(a.cprice_amt, b.cprice_amt) cprice_amt, NVL(a.int_amt, b.int_amt) int_amt, NVL(a.fprice_amt, b.fprice_amt) fprice_amt, NVL(a.yield, b.yield) yield, NVL(a.exer_yield, b.exer_yield) exer_yield, NVL(a.calculate_field, b.calculate_field) calculate_field, NVL(a.trade_status, b.trade_status) trade_status, NVL(a.send_status, b.send_status) send_status, NVL(a.execid, b.execid) execid, NVL(a.re_eff_time, b.re_eff_time) re_eff_time, NVL(a.workflow_id, NULL) workflow_id, NVL(a.workflow_status, '01') workflow_status, NVL(a.remark, b.remark) remark, NVL(a.create_user, b.create_user) create_user, NVL(a.create_time, b.create_time) create_time, NVL(a.create_dept, b.create_dept) create_dept, NVL(a.update_user, b.update_user) update_user, NVL(a.update_time, b.update_time) update_time FROM wfl_ibu_quote_bond_det a FULL JOIN ibu_quote_bond_det b ON a.quote_id = b.quote_id) x LEFT JOIN MST_CFETS_CUSTOMER_TRADER m ON m.trader_id = x.cp_trader LEFT JOIN MST_CFETS_CUSTOMER_INFO n ON n.party_id = x.cp_party_id GROUP BY x.quote_id) xx LEFT JOIN ibu_quote_bond_det iqbd ON iqbd.quote_id = xx.quote_id AND iqbd.TRADE_STATUS = '07' LEFT JOIN MST_CFETS_CUSTOMER_TRADER mm ON mm.trader_id = iqbd.cp_trader LEFT JOIN MST_CFETS_CUSTOMER_INFO nn ON nn.party_id = iqbd.cp_party_id
) b on a.QUOTE_ID = b.QUOTE_ID LEFT JOIN TRDQUTO_MATCH_INFO TT1 ON TT1.PRE_TRADE_ID = a.QUOTE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TT2 ON TT2.TOTLE_TRADE_ID = TT1.TRD_ID left join (select f.finprod_id, f.FINPROD_ABBR, f.FINPROD_NAME, f.FINPROD_MARKET_ID, f.MDATE, g.TYPE_6, g.TYPE_7 FROM FIN_PRODUCT f left join FIN_PRODUCT_TYPE g on f.finprod_id = g.finprod_id and g.branch = 0) c on a.finprod_id = c.finprod_id left join MST_CFETS_CUSTOMER_INFO n on n.party_id = a.ou_party_id left join PTL_PORTFOLIO e on e.portfolio_id = a.portfolio_id left join SYS_USER f on a.OU_TRADER_ID = f.USER_NAME left join SYS_USER_ADD fa on fa.USER_ID = f.USER_ID left join MST_CFETS_CUSTOMER_TRADER m on m.trader_id = NVL(fa.IBU_TRADER, a.OU_TRADER_ID) LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'STATUS_VALID')A1 ON A.WORKFLOW_STATUS = A1.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'QUOTE_ROLE_TYPE')B ON A.QUOTE_ROLE_TYPE = B.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'PS')C ON A.PS = C.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'QUOTE_TYPE')D ON A.QUOTE_TYPE = D.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'QUOTE_STUTAS_IBU')E ON A.TRADE_STATUS = E.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'SEND_TYPE_IBU')F ON A.SEND_STATUS = F.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'WINDTYPEONE')H ON C.TYPE_6 = H.ITEM_CODE LEFT JOIN (SELECT QUOTE_ID, LISTAGG(PORTFOLIO_ID, ',') WITHIN GROUP( ORDER BY QUOTE_ID) PORTFOLIO_ID , LISTAGG(ENTRUST_ID, ',') WITHIN GROUP( ORDER BY QUOTE_ID) ENTRUST_ID FROM ( SELECT QUOTE_ID, PORTFOLIO_ID , ENTRUST_ID FROM WFL_IBU_QUOTE_ETR_RE UNION ALL SELECT QUOTE_ID, PORTFOLIO_ID , ENTRUST_ID FROM IBU_QUOTE_ETR_RE ) GROUP BY QUOTE_ID) z ON z.QUOTE_ID = A.QUOTE_ID where a.QUOTE_TYPE ='02'
and (a.ENTRUST_ID = #{entrustId,jdbcType=VARCHAR} or a.QUOTE_ID IN (SELECT iqer.QUOTE_ID FROM IBU_QUOTE_ETR_RE iqer WHERE iqer.ENTRUST_ID = #{entrustId,jdbcType=VARCHAR}) or a.QUOTE_ID IN (SELECT wiqer.QUOTE_ID FROM WFL_IBU_QUOTE_ETR_RE wiqer WHERE wiqer.ENTRUST_ID = #{entrustId,jdbcType=VARCHAR}) )
) y

