AND T1.COUNTER_TRADER IN
#{item}
AND T1.COUNTER_ID = #{counterId,jdbcType=VARCHAR}
AND T2.FINPROD_MARKET_ID = #{finprodAbbr,jdbcType=VARCHAR}
AND T1.TOTLE_TRADE_ID = #{quoteId,jdbcType=VARCHAR}
and T1.TOTLE_TRADE_ID in
#{item}
and (T8.STATISTICAL_TIMES = 0 OR T8.STATISTICAL_TIMES IS null)
and T1.QUOTE_TYPE in
#{item}
AND T1.CREATE_USER = #{loginUserId}
UNION ALL
SELECT '04' validStatus, T1.PS, T1.QUOTE_TYPE, T1.FINPROD_ID, T2.FINPROD_MARKET_ID finprodMarketId, T2.FINPROD_ABBR finprodName, T1.SHARE_AMT / 100 shareAmt, T1.UNIT_CPRICE price, T1.YIELD matureYield, T1.EXER_YIELD exerYield, T5.PARTY_ABBR ouPartyName, CASE WHEN T4.PARTY_ABBR IS NOT NULL THEN t4.PARTY_ABBR ELSE T3.COUNTER_NAME END cpPartyName, CASE WHEN T7.TRADER_NAME IS NOT NULL THEN T7.TRADER_NAME WHEN sua.IBU_TRADER IS NOT NULL THEN sua.IBU_TRADER WHEN T13.USER_NAME IS NOT NULL THEN T13.USER_NAME ELSE T1.OU_TRADER_ID END ouTraderName, T6.TRADER_NAME cpTraderName, T1.SETTLE_SPEED, T1.SETTLE_DATE settleDate, T1.DELIVERY_TYPE , T1.CLEAR_TYPE, T1.TRADE_MARKET, T1.TRADE_DATE tradeDate, case when T1.PS = 'T03' THEN T1.SETTLE_DATE ELSE NULL END theoreticalExerciseDate, T8.STATISTICAL_TIMES statisticalTimes, T1.DELIVERY_TYPE settleMethod, T1.CLEAR_TYPE settleType, T1.TOTLE_TRADE_ID quoteId, NULL actSetteDate , T10.TYPE_12 assetType, NULL trdId, NULL dealDate, '' calMode, T1.INT_AMT intAmt, T1.SETT_CCY settCcy, T1.UNIT_INT unitInt FROM WFL_REG_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY T3 ON T3.COUNTER_ID = T1.COUNTER_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO T4 ON T4.PARTY_ID = T3.PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO T5 ON T5.PARTY_ID = T1.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER T6 ON T6.TRADER_ID = T1.COUNTER_TRADER LEFT JOIN MST_CFETS_CUSTOMER_TRADER T7 ON T7.TRADER_ID = T1.OU_TRADER_ID LEFT JOIN (SELECT ENTRUST_ID, COUNT(1) STATISTICAL_TIMES FROM ETR_ENTRUST_OPER_HIS WHERE OPER_TYPE = #{OPR_TYPE_09} GROUP BY ENTRUST_ID) T8 ON T8.ENTRUST_ID = T1.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE T10 ON T10.FINPROD_ID = T1.FINPROD_ID LEFT JOIN SYS_USER T13 ON T13.USER_NAME = T1.OU_TRADER_ID LEFT JOIN SYS_USER_ADD sua ON sua.USER_ID = T13.USER_ID WHERE PS IN ('T01','T02','T03') and T1.TRADE_DATE = to_date(#{platDate}, 'yyyy-MM-dd')
AND T1.TRADE_MARKET IN
#{item}
AND T1.PS IN
#{item}
AND T1.QUOTE_TYPE IN
#{item}
AND T1.SETTLE_SPEED IN
DECODE(#{item},'01',0,'02',1,'03',2)
AND T1.OU_TRADER_ID IN
#{item}
AND T1.COUNTER_TRADER IN
#{item}
AND T1.COUNTER_ID = #{counterId,jdbcType=VARCHAR}
AND T2.FINPROD_MARKET_ID = #{finprodAbbr,jdbcType=VARCHAR}
AND T1.TOTLE_TRADE_ID = #{quoteId,jdbcType=VARCHAR}
and T1.TOTLE_TRADE_ID in
#{item}
and (T8.STATISTICAL_TIMES = 0 OR T8.STATISTICAL_TIMES IS null)
and T1.QUOTE_TYPE in
#{item}
AND T1.CREATE_USER = #{loginUserId}
) TT LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'STATUS_VALID')D ON TT.validStatus = D.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'PS')E ON TT.PS = E.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'QUOTE_STYLE')F ON TT.QUOTE_TYPE = F.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'CUSTOM_ASSET_TYPE_FOUR')G ON TT.assetType = G.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'ACCOUNT_SPEED')H ON DECODE(TT.SETTLE_SPEED,0,'01',1,'02',2,'03') = H.ITEM_CODE LEFT JOIN (SELECT ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST T WHERE T.DICT_CODE= 'TRADE_PLACE')I ON TT.TRADE_MARKET = I.ITEM_CODE
( D.ITEM_VALUE like '%' || #{search} || '%' OR E.ITEM_VALUE like '%' || #{search} || '%' OR F.ITEM_VALUE like '%' || #{search} || '%' OR TT.finprodMarketId like '%' || #{search} || '%' OR TT.finprodName like '%' || #{search} || '%' OR G.ITEM_VALUE like '%' || #{search} || '%' OR to_char(TT.shareAmt,'FM99999.90')=#{search} or to_char(TT.price,'FM99990.9999')=#{search} or TT.price||'' =#{search} or to_char(TT.matureYield*100,'FM99990.9999')=#{search} or TT.matureYield||'' =#{search} or to_char(TT.exerYield*100,'FM99990.9999')=#{search} or TT.exerYield||'' =#{search} or TT.ouPartyName like '%' || #{search} || '%' OR TT.cpPartyName like '%' || #{search} || '%' OR TT.ouTraderName LIKE '%' || #{search} || '%' OR TT.cpTraderName LIKE '%' || #{search} || '%' OR H.ITEM_VALUE like '%' || #{search} || '%' OR to_char(TT.settleDate,'yyyy-MM-dd') LIKE '%' || #{search} || '%' OR I.ITEM_VALUE like '%' || #{search} || '%' OR to_char(TT.theoreticalExerciseDate,'yyyy-MM-dd') LIKE '%' || #{search} || '%' OR to_char(TT.actSetteDate,'yyyy-MM-dd') LIKE '%' || #{search} || '%' OR to_char(TT.tradeDate,'yyyy-MM-dd') LIKE '%' || #{search} || '%' OR to_char(TT.statisticalTimes,'FM99990.9999')=#{search} or TT.statisticalTimes||'' =#{search} or TT.quoteId LIKE '%' || #{search} || '%' OR TT.trdId LIKE '%' || #{search} || '%'
or to_char(TT.theoreticalExerciseDate,'yyyy-MM-dd')||'' =#{search} or to_char(TT.theoreticalExerciseDate,'yyyy-MM-dd')=#{year}||'-'||#{search} or replace(to_char(TT.theoreticalExerciseDate,'yyyy-MM-dd'),'-','/')=#{search} or replace(to_char(TT.theoreticalExerciseDate,'yyyy-MM-dd'),'-','/')=#{year}||'/'||#{search}
or to_char(TT.actSetteDate,'yyyy-MM-dd')||'' =#{search} or to_char(TT.actSetteDate,'yyyy-MM-dd')=#{year}||'-'||#{search} or replace(to_char(TT.actSetteDate,'yyyy-MM-dd'),'-','/')=#{search} or replace(to_char(TT.actSetteDate,'yyyy-MM-dd'),'-','/')=#{year}||'/'||#{search}
or to_char(TT.tradeDate,'yyyy-MM-dd')||'' =#{search} or to_char(TT.tradeDate,'yyyy-MM-dd')=#{year}||'-'||#{search} or replace(to_char(TT.tradeDate,'yyyy-MM-dd'),'-','/')=#{search} or replace(to_char(TT.tradeDate,'yyyy-MM-dd'),'-','/')=#{year}||'/'||#{search} )
order by ${pageMode.sort} ${pageMode.direction}

select sum(nvl(nvl(ee.ENTRUST_NUM*100,0) - nvl(rfpd.ENTRUST_AMT, 0) - nvl(wrfpd.SHARE_AMT*100, 0) - nvl(IBQER.ENTRUST_AMT, 0) - nvl(wiqer.SHARE_AMT*100, 0),0)) avaNum from ETR_ENTRUST ee left join ETR_ENTRUST_ADD eea on ee.ENTRUST_ID = eea.ENTRUST_ID left join (select t.SHARE_AMT*100 ENTRUST_AMT, t.ENTRUST_ID from REG_FIN_PRODUCT_DEAL t left join reg_FIN_PRODUCT_DEAL_TOTAL rfpdt on rfpdt.TOTLE_TRADE_ID = t.TOTLE_TRADE_ID where rfpdt.IS_CANCEL = 'N' and rfpdt.TRADE_STATUS = '01' ) rfpd on rfpd.ENTRUST_ID = ee.ENTRUST_ID left join WFL_REG_FIN_PRODUCT_DEAL wrfpd on wrfpd.ENTRUST_ID = ee.ENTRUST_ID
and wrfpd.TOTLE_TRADE_ID != #{totleTradeId}
left join ( select t.SHARE_AMT*100 ENTRUST_AMT, t.ENTRUST_ID from IBU_QUOTE_ETR_RE t left join IBU_QUOTE_BOND IQB on t.QUOTE_ID = IQB.QUOTE_ID where IQB.SEND_STATUS = '01' ) IBQER on rfpd.ENTRUST_ID = ee.ENTRUST_ID left join WFL_IBU_QUOTE_ETR_RE wiqer on wiqer.ENTRUST_ID = ee.ENTRUST_ID
and wiqer.QUOTE_ID != #{totleTradeId}
where ee.ENTRUST_ID = #{entrustId}
